//! C interface to dsd2pcm: whole-file DSD64 to WAV conversion and Super Audio CD frame
//! runs to PCM. The header is `include/dsd2pcm.h`, generated by cbindgen from this crate;
//! docs/c-api.md describes the interface.
//!
//! Rules of the interface: every pointer is checked for NULL, every buffer comes with its
//! length, no panic crosses the boundary (each entry point catches it and returns
//! [`DSD2PCM_E_INTERNAL`]), and the only memory the caller frees is a converter handle,
//! with `dsd2pcm_frames_free`. Paths are NUL-terminated: raw bytes on Unix, UTF-8 elsewhere.
//! Every struct starts with its `struct_size` (ABI versioning, see docs/c-api.md).
//!
//! The `unsafe` code (raw pointers, `#[no_mangle]`) is all in `ffi.rs`; this module holds
//! the types, constants and the safe helpers.
#![deny(unsafe_code)]
#![allow(non_camel_case_types)]

// The Rust library, which has this crate's library name too.
extern crate dsd2pcm as dsd;

use dsd::frames::MAX_CHANNELS;
use dsd::{Cutoff, Error, Filter, PcmRate};
use std::any::Any;
use std::cell::RefCell;
use std::ffi::{c_char, c_int, c_void, CString};
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::sync::Mutex;

#[allow(unsafe_code)]
mod ffi;
#[cfg(test)]
#[allow(unsafe_code)]
mod tests;

/// Success.
pub const DSD2PCM_OK: c_int = 0;
/// A required pointer argument is NULL.
pub const DSD2PCM_E_NULL: c_int = 1;
/// An argument is out of range: a rate, cutoff, filter, format, channel count, gain or
/// thread value, a `struct_size` below the 0.1.0 size, a buffer length, a misaligned or
/// overlapping buffer, an empty path, a path that is not UTF-8 (outside Unix).
pub const DSD2PCM_E_INVALID_ARGUMENT: c_int = 2;
/// An operating-system I/O error.
pub const DSD2PCM_E_IO: c_int = 3;
/// The input is not a valid DSF, DFF, WAV or FLAC file, or is truncated.
pub const DSD2PCM_E_FORMAT: c_int = 4;
/// The input or a setting is valid but not supported by this version.
pub const DSD2PCM_E_UNSUPPORTED: c_int = 5;
/// The progress callback asked to stop.
pub const DSD2PCM_E_CANCELLED: c_int = 6;
/// The converter handle is in use by another thread.
pub const DSD2PCM_E_BUSY: c_int = 7;
/// An internal error (a caught panic, or a handle unusable after one). Please report it.
pub const DSD2PCM_E_INTERNAL: c_int = 8;

/// Output layout: packed 3-byte little-endian samples (24-bit WAV and FLAC).
pub const DSD2PCM_FORMAT_S24LE: u32 = 0;
/// Output layout: sign-extended 24-bit samples in native-endian `int32_t`.
pub const DSD2PCM_FORMAT_I32: u32 = 1;

/// Low-pass filter: passband to 40 kHz, stopband from 48 kHz (the default).
pub const DSD2PCM_CUTOFF_STANDARD: u32 = 0;
/// Low-pass filter: passband to 30 kHz, stopband from 36 kHz.
pub const DSD2PCM_CUTOFF_LOW: u32 = 1;
/// Low-pass filter: passband to 80 kHz (176 400 and 352 800 Hz only).
pub const DSD2PCM_CUTOFF_WIDE: u32 = 2;

/// Filter and quantiser: scarletbook-pcm 0.7.0's (the default).
pub const DSD2PCM_FILTER_DEFAULT: u32 = 0;
/// Filter and quantiser: pysacd's filter with its TPDF-dithered quantiser, at 88200 and
/// 176400 Hz with the standard cutoff. The dither is seeded per Super Audio CD frame from
/// its index in the area: files count from their start, frame runs from
/// `dsd2pcm_run.first_frame`.
pub const DSD2PCM_FILTER_PYSACD: u32 = 1;
/// Filter and quantiser: the precise filter, at every rate and cutoff, rounded as the
/// default: at least 150 dB of stopband where ultrasonic content folds into the passband,
/// at a higher CPU cost.
pub const DSD2PCM_FILTER_PRECISE: u32 = 2;

/// The ABI version: it changes on any incompatible change to the interface. Compatible
/// changes only append fields to the structs (see `struct_size`) or add functions.
pub const DSD2PCM_ABI_VERSION: u32 = 1;

/// Bytes of one channel in one Super Audio CD frame.
pub const DSD2PCM_FRAME_BYTES_PER_CHANNEL: usize = 4704;
/// The highest channel count.
pub const DSD2PCM_MAX_CHANNELS: usize = 6;

const _: () = assert!(DSD2PCM_FRAME_BYTES_PER_CHANNEL == dsd::frames::FRAME_BYTES_PER_CHANNEL);
const _: () = assert!(DSD2PCM_MAX_CHANNELS == MAX_CHANNELS as usize);

/// Progress callback: `done` of `total` output samples per channel are written. Called on
/// the thread that called the conversion, once before the first block and after each block.
/// Return 0 to continue, any other value to stop with `DSD2PCM_E_CANCELLED`. It must not
/// unwind (C++ exceptions, longjmp) into the library.
pub type dsd2pcm_progress_fn =
    Option<unsafe extern "C" fn(done: u64, total: u64, user_data: *mut c_void) -> c_int>;

/// Settings for `dsd2pcm_convert_file`. Start from `DSD2PCM_FILE_OPTIONS_INIT` (all zeros
/// but `struct_size`) and set `rate_hz`; the other zeros are the defaults: standard cutoff,
/// default filter, 0 dB, all cores, no callback.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct dsd2pcm_file_options {
    /// Size of this struct as the caller compiled it: `sizeof(...)` (the `*_INIT` macro sets
    /// it). Must be at least the 0.1.0 size; the library reads or writes only the fields it
    /// knows.
    pub struct_size: u32,
    /// Output rate: 88200, 176400 or 352800.
    pub rate_hz: u32,
    /// `DSD2PCM_CUTOFF_*`.
    pub cutoff: u32,
    /// `DSD2PCM_FILTER_*`; 0 is the default.
    pub filter: u32,
    /// 0: convert on all cores; 1: on the calling thread only. Other values are reserved.
    pub threads: u32,
    /// Gain in dB, -120 to +24.
    pub gain_db: f64,
    /// Progress callback, or NULL.
    pub progress: dsd2pcm_progress_fn,
    /// Passed to `progress` unchanged.
    pub user_data: *mut c_void,
}

/// What `dsd2pcm_convert_file` did; written on success only. Start from
/// `DSD2PCM_FILE_REPORT_INIT`.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct dsd2pcm_file_report {
    /// Size of this struct as the caller compiled it: `sizeof(...)` (the `*_INIT` macro sets
    /// it). Must be at least the 0.1.0 size; the library reads or writes only the fields it
    /// knows.
    pub struct_size: u32,
    /// Input rate in Hz.
    pub in_rate: u32,
    /// Output rate in Hz.
    pub out_rate: u32,
    /// Channels.
    pub channels: u32,
    /// Input duration in seconds.
    pub seconds: f64,
    /// Output samples per channel.
    pub out_samples: u64,
    /// Samples clamped to 24 bits, per channel (entries past `channels` are 0).
    pub clipped: [u64; DSD2PCM_MAX_CHANNELS],
    /// Sum of `clipped`.
    pub clipped_total: u64,
}

/// Settings for `dsd2pcm_frames_new`. Start from `DSD2PCM_FRAMES_CONFIG_INIT` and set
/// `rate_hz` and `channels`; the other zeros are the defaults: standard cutoff, default
/// filter, 0 dB.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct dsd2pcm_frames_config {
    /// Size of this struct as the caller compiled it: `sizeof(...)` (the `*_INIT` macro sets
    /// it). Must be at least the 0.1.0 size; the library reads or writes only the fields it
    /// knows.
    pub struct_size: u32,
    /// Output rate: 88200, 176400 or 352800.
    pub rate_hz: u32,
    /// `DSD2PCM_CUTOFF_*`.
    pub cutoff: u32,
    /// `DSD2PCM_FILTER_*`; 0 is the default.
    pub filter: u32,
    /// Channels of the frames, 1 to 6.
    pub channels: u32,
    /// Gain in dB, -120 to +24.
    pub gain_db: f64,
}

/// A run of consecutive frames of one area and the frames around it. Frames are
/// `channels x 4704` bytes, channels interleaved byte by byte.
///
/// The frames are either in one buffer (`frames`, `frames_len` a whole number of frames)
/// or one buffer per frame (`frame_ptrs`, `frame_count` pointers to one frame each); set
/// the other pair to NULL and 0. `before` and `after` are the neighbour frames, NULL with
/// length 0 at an edge of the area (the input beyond is idle). Start from
/// `DSD2PCM_RUN_INIT`.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct dsd2pcm_run {
    /// Size of this struct as the caller compiled it: `sizeof(...)` (the `*_INIT` macro sets
    /// it). Must be at least the 0.1.0 size; the library reads or writes only the fields it
    /// knows.
    pub struct_size: u32,
    /// The frame before the run, or NULL.
    pub before: *const u8,
    /// `before`'s length in bytes: one frame, or 0 with NULL.
    pub before_len: usize,
    /// The frames, back to back, or NULL.
    pub frames: *const u8,
    /// `frames`' length in bytes.
    pub frames_len: usize,
    /// One pointer per frame, or NULL.
    pub frame_ptrs: *const *const u8,
    /// Entries of `frame_ptrs`.
    pub frame_count: usize,
    /// The frame after the run, or NULL.
    pub after: *const u8,
    /// `after`'s length in bytes: one frame, or 0 with NULL.
    pub after_len: usize,
    /// Index of the run's first frame in its area. `DSD2PCM_FILTER_PYSACD` seeds its
    /// dither from it (frame `first_frame + i` for the run's frame `i`); the default filter
    /// ignores it.
    pub first_frame: u64,
}

/// Counts from one `dsd2pcm_frames_convert` call; written on success only. Start from
/// `DSD2PCM_STATS_INIT`.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct dsd2pcm_stats {
    /// Size of this struct as the caller compiled it: `sizeof(...)` (the `*_INIT` macro sets
    /// it). Must be at least the 0.1.0 size; the library reads or writes only the fields it
    /// knows.
    pub struct_size: u32,
    /// Channels of the converter.
    pub channels: u32,
    /// Samples clamped to 24 bits, per channel (entries past the channel count are 0).
    pub clipped: [u64; DSD2PCM_MAX_CHANNELS],
    /// Sum of `clipped`.
    pub clipped_total: u64,
}

/// A frame-run converter (opaque). Create with `dsd2pcm_frames_new`, free with
/// `dsd2pcm_frames_free`. One call at a time: a call while another thread is converting
/// with the same handle returns `DSD2PCM_E_BUSY`.
pub struct dsd2pcm_frames {
    conv: Mutex<dsd::frames::Converter>,
    channels: usize,
    samples_per_frame: usize,
    context_bytes: usize,
}

impl dsd2pcm_frames {
    pub(crate) fn new(conv: dsd::frames::Converter) -> dsd2pcm_frames {
        dsd2pcm_frames {
            channels: usize::from(conv.config().channels),
            samples_per_frame: conv.samples_per_frame(),
            context_bytes: conv.context_bytes(),
            conv: Mutex::new(conv),
        }
    }

    /// Bytes of one frame of all channels.
    pub(crate) fn frame_bytes(&self) -> usize {
        DSD2PCM_FRAME_BYTES_PER_CHANNEL * self.channels
    }

    /// Bytes of output for `frames` frames in `format`, or `None` for an unknown format or
    /// an overflow.
    pub(crate) fn output_bytes(&self, frames: usize, format: u32) -> Option<usize> {
        let size = match format {
            DSD2PCM_FORMAT_S24LE => 3,
            DSD2PCM_FORMAT_I32 => 4,
            _ => return None,
        };
        frames
            .checked_mul(self.samples_per_frame * self.channels * size)
            .filter(|&n| n <= isize::MAX as usize)
    }
}

// ---- Safe helpers ----

/// A struct passed with its `struct_size`: the size of its 0.1.0 (ABI 1) layout, the
/// smallest a caller may pass.
pub(crate) trait Versioned: Copy {
    const NAME: &'static str;
    const V1_SIZE: usize;
    fn set_struct_size(&mut self, size: u32);
}

macro_rules! versioned {
    ($t:ident, $v1_64:expr) => {
        impl Versioned for $t {
            const NAME: &'static str = stringify!($t);
            const V1_SIZE: usize = std::mem::size_of::<$t>();
            fn set_struct_size(&mut self, size: u32) {
                self.struct_size = size;
            }
        }
        // The 0.1.0 layout is a contract: these sizes never shrink or change.
        #[cfg(target_pointer_width = "64")]
        const _: () = assert!(std::mem::size_of::<$t>() == $v1_64);
    };
}

versioned!(dsd2pcm_file_options, 48);
versioned!(dsd2pcm_file_report, 88);
versioned!(dsd2pcm_frames_config, 32);
versioned!(dsd2pcm_run, 80);
versioned!(dsd2pcm_stats, 64);

/// Checks a caller's `struct_size`.
pub(crate) fn check_struct_size<T: Versioned>(size: u32, what: &str) -> Result<(), Fail> {
    if (size as usize) < T::V1_SIZE {
        return Err(invalid(format!(
            "{what}->struct_size {size}: {} needs at least {} (use {}_INIT)",
            T::NAME,
            T::V1_SIZE,
            T::NAME.to_uppercase()
        )));
    }
    Ok(())
}

/// A failure: status code and message.
pub(crate) struct Fail(c_int, String);

impl From<Error> for Fail {
    fn from(e: Error) -> Fail {
        let code = match &e {
            Error::Io(_) => DSD2PCM_E_IO,
            Error::Format(_) => DSD2PCM_E_FORMAT,
            Error::Unsupported(_) => DSD2PCM_E_UNSUPPORTED,
            Error::InvalidArgument(_) => DSD2PCM_E_INVALID_ARGUMENT,
            Error::Cancelled => DSD2PCM_E_CANCELLED,
            _ => DSD2PCM_E_INTERNAL,
        };
        Fail(code, e.to_string())
    }
}

pub(crate) fn null(name: &str) -> Fail {
    Fail(DSD2PCM_E_NULL, format!("{name} is NULL"))
}

pub(crate) fn invalid(msg: impl Into<String>) -> Fail {
    Fail(DSD2PCM_E_INVALID_ARGUMENT, msg.into())
}

thread_local! {
    static LAST_ERROR: RefCell<CString> = RefCell::new(CString::default());
}

fn set_last_error(msg: &str) {
    let msg = CString::new(msg.replace('\0', " ")).unwrap_or_default();
    // A thread being torn down has no slot left; the code is still returned.
    let _ = LAST_ERROR.try_with(|l| *l.borrow_mut() = msg);
}

pub(crate) fn last_error_ptr() -> *const c_char {
    static EMPTY: &[u8] = b"\0";
    LAST_ERROR
        .try_with(|l| l.borrow().as_ptr())
        .unwrap_or(EMPTY.as_ptr().cast())
}

fn panic_message(p: &(dyn Any + Send)) -> String {
    let what = p
        .downcast_ref::<&str>()
        .copied()
        .or_else(|| p.downcast_ref::<String>().map(String::as_str))
        .unwrap_or("unknown panic");
    format!("internal error: {what}")
}

/// Runs an entry point: catches panics, records the message of a failure in the
/// thread's last error and returns the status code.
pub(crate) fn guard(f: impl FnOnce() -> Result<(), Fail>) -> c_int {
    let (code, msg) = match catch_unwind(AssertUnwindSafe(f)) {
        Ok(Ok(())) => return DSD2PCM_OK,
        Ok(Err(Fail(code, msg))) => (code, msg),
        Err(p) => (DSD2PCM_E_INTERNAL, panic_message(&*p)),
    };
    set_last_error(&msg);
    code
}

/// Runs a query entry point: catches panics; `fallback` on a panic.
pub(crate) fn guard_value<T>(fallback: T, f: impl FnOnce() -> T) -> T {
    catch_unwind(AssertUnwindSafe(f)).unwrap_or(fallback)
}

pub(crate) fn rate(hz: u32) -> Result<PcmRate, Fail> {
    PcmRate::from_hz(hz).ok_or_else(|| invalid(format!("rate {hz} Hz: 88200, 176400 or 352800")))
}

pub(crate) fn cutoff(c: u32) -> Result<Cutoff, Fail> {
    match c {
        DSD2PCM_CUTOFF_STANDARD => Ok(Cutoff::Standard),
        DSD2PCM_CUTOFF_LOW => Ok(Cutoff::Low),
        DSD2PCM_CUTOFF_WIDE => Ok(Cutoff::Wide),
        _ => Err(invalid(format!("cutoff {c}: 0, 1 or 2"))),
    }
}

pub(crate) fn filter(f: u32) -> Result<Filter, Fail> {
    match f {
        DSD2PCM_FILTER_DEFAULT => Ok(Filter::Default),
        DSD2PCM_FILTER_PYSACD => Ok(Filter::Pysacd),
        DSD2PCM_FILTER_PRECISE => Ok(Filter::Precise),
        _ => Err(invalid(format!("filter {f}: 0, 1 or 2"))),
    }
}

pub(crate) fn file_options(o: &dsd2pcm_file_options) -> Result<dsd::PcmOptions, Fail> {
    let mut opts = dsd::PcmOptions::new(rate(o.rate_hz)?);
    opts.cutoff = cutoff(o.cutoff)?;
    opts.filter = filter(o.filter)?;
    opts.threads = match o.threads {
        0 => true,
        1 => false,
        t => return Err(invalid(format!("threads {t}: 0 (all cores) or 1"))),
    };
    opts.gain_db = o.gain_db;
    dsd::convert::check_options(&opts)?;
    Ok(opts)
}

pub(crate) fn frames_config(c: &dsd2pcm_frames_config) -> Result<dsd::frames::PcmConfig, Fail> {
    let (rate, cutoff, filter) = (rate(c.rate_hz)?, cutoff(c.cutoff)?, filter(c.filter)?);
    let channels = u8::try_from(c.channels)
        .ok()
        .filter(|ch| (1..=MAX_CHANNELS).contains(ch))
        .ok_or_else(|| invalid(format!("{} channels: 1 to 6 are supported", c.channels)))?;
    let gain = dsd::frames::Gain::from_db(c.gain_db)?;
    Ok(dsd::frames::PcmConfig::new(rate, cutoff, channels)
        .with_gain(gain)
        .with_filter(filter))
}

pub(crate) fn file_report(r: &dsd::Report) -> dsd2pcm_file_report {
    let mut out = dsd2pcm_file_report {
        struct_size: 0,
        in_rate: r.in_rate,
        out_rate: r.out_rate,
        channels: r.clipped.len() as u32,
        seconds: r.seconds,
        out_samples: r.out_samples,
        ..Default::default()
    };
    for (d, s) in out.clipped.iter_mut().zip(&r.clipped) {
        *d = *s;
    }
    out.clipped_total = r.clipped.iter().sum();
    out
}

/// The static name of a status code.
pub(crate) fn status_str(status: c_int) -> &'static [u8] {
    match status {
        DSD2PCM_OK => b"ok\0",
        DSD2PCM_E_NULL => b"NULL pointer\0",
        DSD2PCM_E_INVALID_ARGUMENT => b"invalid argument\0",
        DSD2PCM_E_IO => b"I/O error\0",
        DSD2PCM_E_FORMAT => b"invalid file\0",
        DSD2PCM_E_UNSUPPORTED => b"unsupported\0",
        DSD2PCM_E_CANCELLED => b"cancelled\0",
        DSD2PCM_E_BUSY => b"converter busy\0",
        DSD2PCM_E_INTERNAL => b"internal error\0",
        _ => b"unknown status\0",
    }
}

/// Address ranges `[start, start + len)` of two buffers overlap (empty buffers never do).
pub(crate) fn overlaps(a: (usize, usize), b: (usize, usize)) -> bool {
    a.1 != 0 && b.1 != 0 && a.0 < b.0.saturating_add(b.1) && b.0 < a.0.saturating_add(a.1)
}
